module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    // Sequential logic for counter and data shifting
    reg [1:0] cnt;
    reg [3:0] data;
    reg valid;

    // Combinational logic for output
    assign dout = data[3];
    assign valid_out = valid;
    // Always block triggered on positive edge of clk or negative edge of rst_n
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            // Asynchronous reset
            cnt <= 2'b0;
            data <= 4'b0;
            valid <= 1'b0;
        end else begin
            // Increment counter and update data
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b0;
                valid <= 1'b1;
            end else begin
                data <= {data[2:0], data[3]};
                cnt <= cnt + 1;
                valid <= 1'b0;
            end
        end
    end
endmodule
